def is_triangle_free(edges, n):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if k in adj[i]:
                    return False
    return True

def is_maximal(edges, n):
    # A triangle-free graph is maximal if adding any missing edge creates a triangle.
    # This is equivalent to saying that for every pair (u, v) not in edges,
    # there exists a vertex w such that (u, w) and (v, w) are in edges.
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for i in range(n):
        for j in range(i + 1, n):
            if j not in adj[i]:
                # Check if adding (i, j) creates a triangle
                # It creates a triangle if i and j have a common neighbor
                if not (adj[i] & adj[j]):
                    return False, (i, j)
    return True, None

# Let's construct K_{10, 10}
# A = {0, 2, 5, 6, 7, 8, 9, 10, 18, 19}
# B = {1, 3, 4, 11, 12, 13, 14, 15, 16, 17}
A = {0, 2, 5, 6, 7, 8, 9, 10, 18, 19}
B = {1, 3, 4, 11, 12, 13, 14, 15, 16, 17}

# Check if fixed edges are consistent with this partition
fixed_edges = [(1,18), (4,18), (16,18), (4,19), (17,18), (11,19), (3,19)]
for u, v in fixed_edges:
    if (u in A and v in A) or (u in B and v in B):
        print(f"Fixed edge {u, v} is not bipartite!")
    else:
        print(f"Fixed edge {u, v} is bipartite.")

# Construct all edges of K_{10, 10}
edges = []
for u in A:
    for v in B:
        edges.append(tuple(sorted((u, v))))

print(f"Number of edges: {len(edges)}")
print(f"Is triangle-free: {is_triangle_free(edges, 20)}")
maximal, missing = is_maximal(edges, 20)
print(f"Is maximal: {maximal}")

